// ==UserScript==
// @name         ID_A4
// @version      1.1.1
// @match        *://*/*
// @grant        GM_log
// @run-at       document-idle
// ==/UserScript==

(function() {
  'use strict';

  // 1. Hàm mở cửa sổ in A4
  function openA4Print(hoten, tuoi) {
    if (!hoten && !tuoi) {
      console.warn('Không tìm thấy dữ liệu họ tên hoặc tuổi bệnh nhân trên HIS.');
      return;
    }

    let ageStr = (tuoi || '').trim().toUpperCase();
    if (ageStr) {
      ageStr = ageStr.replace(/tuổi/gi, 'T').trim();
      if (!ageStr.endsWith('T')) ageStr += ' T';
    }

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Trình duyệt đang chặn Popup. Vui lòng cấp quyền cho phép mở pop-up trên trang này.');
      return;
    }

    const printHtml = `
      <!DOCTYPE html>
      <html lang="vi">
      <head>
        <meta charset="UTF-8">
        <title>TENA4 - In A4</title>
        <style>
          @page {
            size: A4 portrait;
            margin: 4cm;
          }
          * { box-sizing: border-box; margin: 0; padding: 0; }
          html, body {
            width: 100%;
            height: 100%;
            background: #fff;
            font-family: 'Times New Roman', Times, serif;
            overflow: hidden;
          }
          .print-container {
            width: 130mm;
            height: 217mm;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            margin: 0 auto;
            font-weight: bold;
            text-transform: uppercase;
            overflow: hidden;
            word-break: keep-all !important;
            overflow-wrap: normal !important;
            word-wrap: normal !important;
            hyphens: none !important;
          }
          #p-name {
            line-height: 1.15;
            width: 100%;
            word-break: keep-all !important;
            white-space: normal;
          }
          #p-age {
            line-height: 1.15;
            width: 100%;
            margin-top: 15px;
            word-break: keep-all !important;
            white-space: normal;
          }
          @media print {
            body { margin: 0 !important; padding: 0 !important; }
            .print-container { width: 100% !important; height: 100% !important; }
          }
        </style>
      </head>
      <body>
        <div class="print-container" id="container">
          <div id="p-name"></div>
          <div id="p-age"></div>
        </div>
        <script>
          const name = ${JSON.stringify(hoten)};
          const age = ${JSON.stringify(ageStr)};

          const container = document.getElementById('container');
          const nameEl = document.getElementById('p-name');
          const ageEl = document.getElementById('p-age');

          nameEl.innerHTML = name.split(/\\s+/).map(w => '<span class="word" style="display:inline-block; white-space:nowrap;">' + w + '</span>').join(' ');
          ageEl.innerHTML = age.split(/\\s+/).map(w => '<span class="word" style="display:inline-block; white-space:nowrap;">' + w + '</span>').join(' ');

          function autoFitText() {
            let low = 12;
            let high = 220;
            let bestSize = low;
            const maxW = container.clientWidth;
            const maxH = container.clientHeight;

            while (low <= high) {
              let mid = Math.floor((low + high) / 2);
              nameEl.style.fontSize = mid + 'pt';
              ageEl.style.fontSize = Math.max(8, mid - 4) + 'pt';

              let wordOverflow = false;
              const words = container.querySelectorAll('.word');
              for (let i = 0; i < words.length; i++) {
                if (words[i].offsetWidth > maxW) {
                  wordOverflow = true;
                  break;
                }
              }

              const isOverflow = wordOverflow || container.scrollHeight > maxH || container.scrollWidth > maxW;
              if (!isOverflow) {
                bestSize = mid;
                low = mid + 1;
              } else {
                high = mid - 1;
              }
            }

            nameEl.style.fontSize = bestSize + 'pt';
            ageEl.style.fontSize = Math.max(8, bestSize - 4) + 'pt';
          }

          document.fonts.ready.then(() => {
            autoFitText();
            setTimeout(() => {
              window.print();
            }, 250);
          });
        </script>
      </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(printHtml);
    printWindow.document.close();
  }

  // 2. Hàm đọc thông tin bệnh nhân từ DOM
  function triggerPrintFromHIS() {
    const getVal = (id) => {
      const el = document.getElementById(id);
      if (!el) return '';
      return (el.value || el.innerText || el.textContent || '').trim();
    };

    const hoten = getVal('hoten').toUpperCase();
    const tuoi = getVal('tuoi').toUpperCase();

    openA4Print(hoten, tuoi);
  }

  // 3. Lắng nghe tổ hợp phím Shift + I
  window.addEventListener('keydown', (e) => {
    // KHI BẠN ĐANG GÕ VĂN BẢN (TRONG INPUT/TEXTAREA), SẼ BỎ QUA PHÍM TẮT NÀY
    const activeElement = document.activeElement;
    if (activeElement) {
      const tagName = activeElement.tagName.toLowerCase();
      const isEditable = activeElement.isContentEditable || tagName === 'input' || tagName === 'textarea';
      if (isEditable) {
        return; // Thoát hàm để trả lại thao tác gõ chữ 'I' in hoa bình thường
      }
    }

    if (e.shiftKey && (e.key === 'I' || e.key === 'i')) {
      e.preventDefault();
      e.stopPropagation();
      triggerPrintFromHIS();
    }
  }, true);

  GM_log('Đã nạp phím tắt Shift+I để in A4 trên HIS (đã fix lỗi gõ chữ).');
})();

// ==UserScript==
// @name         AUTO_CAPCHA
// @version      3.2.0
// @match        *://*/*
// @run-at       document-idle
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  // 1. Tập mẫu đã học sẵn (Định dạng ma trận 2D đã kẹp viền)
  const TEMPLATES = [
    // --- HOA ---
   { char: "A", grid: ["0001000","0011100","0011100","0110010","0111110","1100001","1100001"] },
    { char: "B", grid: ["1111110","1100001","1100001","1111110","1100001","1100001","1111110"] },
    { char: "C", grid: ["0111110","1100001","1100000","1100000","1100000","1100001","0111110"] },
   { char: "D", grid: ["1111110","1100001","1100001","1100001","1100001","1100001","1111110"] },
    { char: "E", grid: ["1111111", "1100000", "1100000", "1111110", "1100000", "1100000", "1111111"] },
    { char: "F", grid: ["1111111", "1100000", "1100000", "1111000", "1100000", "1100000", "1100000"] },
    { char: "G", grid: ["0111110","1100001","1100000","1100000","1100111","1100001","0111110"] },
    { char: "H", grid: ["1100001", "1100001", "1100001", "1111111", "1100001", "1100001", "1100001"] },
    { char: "I", grid: ["1111111", "0011000", "0011000", "0011000", "0011000", "0011000", "1111111"] },
    { char: "J", grid: ["0000011", "0000011", "0000011", "0000011", "0000011", "1000011", "0111110"] },
    { char: "K", grid: ["1100001", "1100110", "1111000", "1100000", "1111000", "1100110", "1100001"] },
    { char: "L", grid: ["1100000", "1100000", "1100000", "1100000", "1100000", "1100000", "1111111"] },
    { char: "M", grid: ["1000001", "1100011", "1110101", "1101001", "1100001", "1100001", "1100001"] },
   { char: "N", grid: ["1000001","1100001","1110001","1101001","1100101","1100011","1100001"] },
   { char: "O", grid: ["0111110","1100001","1100001","1100001","1100001","1100001","0111110"] },
{ char: "O", grid: ["0111110","1100001","1100001","1100001","1100001","1100001","0111110"] },
    { char: "P", grid: ["1111110", "1100001", "1100001", "1111110", "1100000", "1100000", "1100000"] },
    { char: "Q", grid: ["0111110","1100001","1100001","1100001","1100101","1100010","0111101"] },
    { char: "R", grid: ["1111110", "1100001", "1100001", "1111110", "1100100", "1100010", "1100001"] },
    { char: "S", grid: ["0111110", "1100001", "1100000", "0111110", "0000011", "1000011", "0111110"] },
    { char: "T", grid: ["1111111", "0011000", "0011000", "0011000", "0011000", "0011000", "0011000"] },
    { char: "U", grid: ["1100001", "1100001", "1100001", "1100001", "1100001", "1100001", "0111110"] },
    { char: "V", grid: ["1100001","1100001","0110010","0110010","0011100","0011100","0001000"] },
    { char: "W", grid: ["10001", "10001", "10001", "10101", "10101", "10101", "01010"] },
{ char: "W", grid: ["1100001","1100001","1100001","1101001","1110101","1100011","1000001"] },
    { char: "X", grid: ["1100001","0110010","0011100","0001000","0011100","0110010","1100001"] },
{ char: "Y", grid: ["1100001","0110010","0011100","0011000","0011000","0011000","0011000"] },
  { char: "Z", grid: ["1111111","0000110","0001100","0011000","0110000","1100000","1111111"] },

    // --- SỐ ---
    { char: "0", grid: ["01110", "10011", "10101", "11001", "10001", "10001", "01110"] },
    { char: "1", grid: ["00100", "01100", "00100", "00100", "00100", "00100", "11111"] },
    { char: "2", grid: ["01110", "10001", "00001", "00010", "00100", "01000", "11111"] },
    { char: "3", grid: ["11110", "00001", "00001", "01110", "00001", "00001", "11110"] },
    { char: "4", grid: ["00010", "00110", "01010", "10010", "11111", "00010", "00010"] },
    { char: "5", grid: ["11111", "10000", "11110", "00001", "00001", "00001", "11110"] },
    { char: "6", grid: ["01110", "10000", "11110", "10001", "10001", "10001", "01110"] },
    { char: "7", grid: ["11111", "00001", "00010", "00100", "01000", "01000", "01000"] },
    { char: "8", grid: ["01110", "10001", "10001", "01110", "10001", "10001", "01110"] },
    { char: "9", grid: ["01110", "10001", "10001", "01111", "00001", "00001", "01110"] },

    // --- THƯỜNG ---
    { char: "r", grid: ["11000", "11100", "11000", "11111", "00000", "01100", "00011"] }
  ];

  // 2. Kẹp biên ma trận
  function trim2DGrid(grid) {
    if (!grid || grid.length === 0) return [];
    let top = 0, bottom = grid.length - 1;
    let left = Infinity, right = -1;

    for (let r = 0; r < grid.length; r++) {
      for (let c = 0; c < grid[r].length; c++) {
        if (grid[r][c] === "1") {
          if (c < left) left = c;
          if (c > right) right = c;
        }
      }
    }
    if (left === Infinity) return [];

    while (top <= bottom && !grid[top].includes("1")) top++;
    while (bottom >= top && !grid[bottom].includes("1")) bottom--;

    const cropped = [];
    for (let r = top; r <= bottom; r++) {
      cropped.push(grid[r].substring(left, right + 1));
    }
    return cropped;
  }

  // 3. Tính độ tương đồng không gian 2D (IoU)
  function calculate2DSimilarity(gridA, gridB) {
    const a = trim2DGrid(gridA);
    const b = trim2DGrid(gridB);
    if (!a.length || !b.length) return 0;

    const maxH = Math.max(a.length, b.length);
    const maxW = Math.max(a[0].length, b[0].length);

    let intersection = 0;
    let union = 0;

    for (let r = 0; r < maxH; r++) {
      for (let c = 0; c < maxW; c++) {
        const bitA = (a[r] && a[r][c]) === "1" ? 1 : 0;
        const bitB = (b[r] && b[r][c]) === "1" ? 1 : 0;

        if (bitA === 1 && bitB === 1) intersection++;
        if (bitA === 1 || bitB === 1) union++;
      }
    }

    return union === 0 ? 0 : (intersection / union);
  }

  // 4. Giải mã và In Log chi tiết
  function giaiVaDienCaptcha() {
    const textEl = document.querySelector(".realperson-text");
    const inputEl = document.getElementById("defaultReal");
    if (!textEl || !inputEl) return false;

    let html = textEl.innerHTML;
    html = html.replace(/&nbsp;/g, " ").replace(/<br\s*[\/]?>/gi, "\n");
    const lines = html.split("\n").map(l => l.replace(/\r/g, ""));
    while (lines.length > 0 && lines[0].trim() === "") lines.shift();
    while (lines.length > 0 && lines[lines.length - 1].trim() === "") lines.pop();
    if (lines.length === 0) return false;

    const maxLen = Math.max(...lines.map(l => l.length));
    const fullGrid = lines.map(line => {
      let r = "";
      for (let i = 0; i < maxLen; i++) {
        r += (line[i] && /[oO0]/.test(line[i])) ? "1" : "0";
      }
      return r;
    });

    const segments = [];
    let inChar = false;
    let start = 0;

    for (let c = 0; c < maxLen; c++) {
      const hasBit = fullGrid.some(row => row[c] === "1");
      if (hasBit && !inChar) {
        inChar = true;
        start = c;
      } else if (!hasBit && inChar) {
        inChar = false;
        segments.push({ start, end: c });
      }
    }
    if (inChar) segments.push({ start, end: maxLen });

    console.group(`%c[CAPTCHA SOLVER DEBUG] - Quét lúc: ${new Date().toLocaleTimeString()}`, "color: #00bcd4; font-weight: bold;");

    let ketQua = "";
    segments.forEach((seg, idx) => {
      const rawCharGrid = fullGrid.map(row => row.substring(seg.start, seg.end));
      const croppedGrid = trim2DGrid(rawCharGrid);

      let bestChar = "?";
      let highestScore = -1;

      for (const tpl of TEMPLATES) {
        const score = calculate2DSimilarity(croppedGrid, tpl.grid);
        if (score > highestScore) {
          highestScore = score;
          bestChar = tpl.char;
        }
      }

      // Bộ tinh chỉnh các cặp hay nhầm lẫn
      const h = croppedGrid.length;
      if ((bestChar === "S" || bestChar === "5") && croppedGrid[0]) {
        bestChar = croppedGrid[0].startsWith("1111") ? "5" : "S";
      }
      if (bestChar === "I" || bestChar === "L" || bestChar === "1") {
        if (croppedGrid[0] && croppedGrid[h - 1]) {
          const topW = croppedGrid[0].replace(/0/g, "").length;
          const botW = croppedGrid[h - 1].replace(/0/g, "").length;
          if (topW >= 4 && botW >= 4) bestChar = "I";
          else if (topW <= 2 && botW >= 4) bestChar = "L";
          else if (topW <= 3 && botW <= 3) bestChar = "1";
        }
      }

      ketQua += bestChar;

      // Vẽ hình dạng ASCII visual để người dùng xem trực quan
      const asciiVisual = croppedGrid.map(row => row.replace(/1/g, "██").replace(/0/g, "  ")).join("\n");

      // Đoạn JSON sinh sẵn để người dùng copy đè nếu sai
      const codeToCopy = `{ char: "${bestChar}", grid: ${JSON.stringify(croppedGrid)} },`;

      console.groupCollapsed(
        `%cKý tự [${idx + 1}]: %c${bestChar} %c(Độ khớp: ${(highestScore * 100).toFixed(1)}%)`,
        "color: #888;",
        "color: #ff9800; font-size: 14px; font-weight: bold;",
        highestScore >= 0.75 ? "color: #4caf50;" : "color: #f44336; font-weight: bold;"
      );
      console.log("Hình dạng quét được:\n" + asciiVisual);
      console.log("%cCode copy để bổ sung/chỉnh sửa vào TEMPLATES:", "color: #2196f3; font-weight: bold;");
      console.log(codeToCopy);
      console.groupEnd();
    });

    console.log(`%c=> TỔNG CHUỖI NHẬN DIỆN: ${ketQua}`, "color: #4caf50; font-size: 16px; font-weight: bold;");
    console.groupEnd();

    // Điền vào ô input
    if (ketQua.length === 4) {
      inputEl.value = ketQua;
      inputEl.dispatchEvent(new Event("input", { bubbles: true }));
      inputEl.dispatchEvent(new Event("change", { bubbles: true }));
      inputEl.dispatchEvent(new KeyboardEvent("keyup", { bubbles: true }));
      return true;
    }

    return false;
  }

  setTimeout(giaiVaDienCaptcha, 450);

  const observer = new MutationObserver(() => {
    const textEl = document.querySelector(".realperson-text");
    if (textEl && textEl.innerHTML.includes("ooo")) {
      giaiVaDienCaptcha();
    }
  });

  observer.observe(document.body, { childList: true, subtree: true });
})();

