            if (!dynamicStyle) {
                dynamicStyle = document.createElement('style');
                dynamicStyle.id = 'dynamic-col-width';
                (document.head || document.documentElement).appendChild(dynamicStyle);
            }
            // Khóa cứng bằng CSS !important ở cả 3 tầng: header (th), thân bảng (td) và hàng ẩn (.jqgfirstrow)
            dynamicStyle.textContent = `
                .ui-jqgrid-htable th:nth-child(${NAME_COL_INDEX}),
                #list_benhnhan tr.jqgfirstrow td:nth-child(${NAME_COL_INDEX}),
                #list_benhnhan tr.jqgrow td:nth-child(${NAME_COL_INDEX}) {
                    width: ${widthPx}px !important;
                    min-width: ${widthPx}px !important;
                    max-width: ${widthPx}px !important;
                }
            `;
        }

        // Đo chiều rộng chuỗi text bằng Canvas
        function getTextWidth(text, font) {
            const canvas = getTextWidth.canvas || (getTextWidth.canvas = document.createElement("canvas"));
            const context = canvas.getContext("2d");
            context.font = font;
            const metrics = context.measureText(text);
            return metrics.width;
        }

        // Tính toán và cố định chiều rộng cột Họ Tên
        function autoFitNameColumn() {
            const rows = document.querySelectorAll('#list_benhnhan tr.jqgrow');
            if (!rows.length) return;

            const sampleCell = rows[0].querySelector(`td:nth-child(${NAME_COL_INDEX})`);
            if (!sampleCell) return;

            const computedStyle = window.getComputedStyle(sampleCell);
            const font = `${computedStyle.fontSize} ${computedStyle.fontFamily}`;

            let maxTextWidth = 0;

            rows.forEach(tr => {
                const cell = tr.querySelector(`td:nth-child(${NAME_COL_INDEX})`);
                if (!cell) return;
                const text = (cell.innerText || cell.textContent || '').trim();
                const width = getTextWidth(text, font);
                if (width > maxTextWidth) {
                    maxTextWidth = width;
                }
            });

            if (maxTextWidth === 0) return;

            // Độ rộng = Text dài nhất + vùng chấm tròn (28px) + đệm an toàn (25px)
            const targetWidth = Math.ceil(maxTextWidth + TRIGGER_WIDTH + 25);

            // Chỉ cập nhật lại CSS khi có sự chênh lệch lớn
            if (Math.abs(targetWidth - currentCalculatedWidth) > 3) {
                currentCalculatedWidth = targetWidth;
                applyDynamicColWidthCSS(targetWidth);
            }
        }

        function updateButtonStatus(connected) {
            isFirebaseConnected = connected;
            const btn = document.getElementById('btnSortFollowed');
            if (!btn) return;

            if (connected) {
                btn.classList.remove('disconnected');
                btn.title = 'Đã kết nối Firebase - Đưa bệnh nhân theo dõi lên đầu';
            } else {
                btn.classList.add('disconnected');
                btn.title = 'Mất kết nối Firebase - Không thể tải hoặc lưu dữ liệu';
            }
        }

        async function fetchCloudData() {
            try {
                const res = await fetch(FIREBASE_ENDPOINT);
                if (res.ok) {
                    const data = await res.json();
                    cachedFollowedList = Array.isArray(data) ? data : [];
                    updateButtonStatus(true);
                    syncStatus();
                } else {
                    updateButtonStatus(false);
                }
            } catch (err) {
                console.warn('Lỗi kết nối Firebase Realtime Database:', err);
                updateButtonStatus(false);
            }
        }

        async function saveCloudData(newList) {
            cachedFollowedList = newList;
            syncStatus();

            try {
                const res = await fetch(FIREBASE_ENDPOINT, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(newList)
                });
                if (res.ok) {
                    updateButtonStatus(true);
                } else {
                    updateButtonStatus(false);
                }
            } catch (err) {
                console.error('Lỗi khi ghi dữ liệu lên Firebase:', err);
                updateButtonStatus(false);
            }
        }

        function syncStatus() {
            const rows = document.querySelectorAll('#list_benhnhan tr.jqgrow');
            rows.forEach(tr => {
                const idCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
                const pId = idCell ? idCell.textContent.trim() : '';
                if (pId && cachedFollowedList.includes(pId)) {
                    tr.setAttribute('data-followed', 'true');
                } else {
                    tr.removeAttribute('data-followed');
                }
            });
            autoFitNameColumn();
        }

        function sortFollowed() {
            if (!isFirebaseConnected) {
                alert('Chưa kết nối được với Firebase, không thể sắp xếp dữ liệu đồng bộ.');
                return;
            }

            const table = document.querySelector('#list_benhnhan tbody') || document.querySelector('#list_benhnhan');
            if (!table) return;

            const rows = Array.from(table.querySelectorAll('tr.jqgrow'));
            if (!rows.length) return;

            rows.sort((a, b) => {
                const idA = a.querySelector('td[aria-describedby*="SOBENHAN_HT"]')?.textContent.trim() || '';
                const idB = b.querySelector('td[aria-describedby*="SOBENHAN_HT"]')?.textContent.trim() || '';
                const followA = cachedFollowedList.includes(idA) ? -1 : 1;
                const followB = cachedFollowedList.includes(idB) ? -1 : 1;
                return followA - followB;
            });

            rows.forEach(tr => table.appendChild(tr));
            autoFitNameColumn();
        }

        // Shift + Click để bật/tắt theo dõi
        document.addEventListener('click', function(e) {
            const targetCell = e.target.closest('#list_benhnhan tr.jqgrow td:nth-child(' + NAME_COL_INDEX + ')');
            if (!targetCell) return;

            const rect = targetCell.getBoundingClientRect();
            if ((e.clientX - rect.left) > (rect.width - TRIGGER_WIDTH)) {
                if (!e.shiftKey) return;

                const tr = targetCell.closest('tr');
                const idCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
                const pId = idCell ? idCell.textContent.trim() : '';
                const pName = targetCell.textContent.trim();

                if (!pId) return;

                let list = [...cachedFollowedList];
                const idx = list.indexOf(pId);

                if (confirm(idx > -1 ? `Bỏ theo dõi bệnh nhân: ${pName}?` : `Theo dõi bệnh nhân: ${pName}?`)) {
                    if (idx > -1) {
                        list.splice(idx, 1);
                    } else {
                        list.push(pId);
                    }
                    saveCloudData(list);
                }
                e.stopPropagation();
            }
        }, true);

        function injectButton() {
            if (document.getElementById('btnSortFollowed')) return;
            const refBtn = document.getElementById('lammoi') || document.querySelector('button[onclick*="lammoi"]');
            if (refBtn && refBtn.parentNode) {
                const btn = document.createElement('button');
                btn.id = 'btnSortFollowed';
                btn.type = 'button';
                btn.className = isFirebaseConnected ? 'btn-sort-followed' : 'btn-sort-followed disconnected';
                btn.title = isFirebaseConnected ? 'Đã kết nối Firebase - Đưa bệnh nhân theo dõi lên đầu' : 'Đang kết nối Firebase...';
                btn.innerHTML = HEROICON_STAR;
                btn.onclick = sortFollowed;
                refBtn.parentNode.insertBefore(btn, refBtn.nextSibling);
            }
        }

        // Giám sát mọi thay đổi của bảng để duy trì CSS
        let resizeDebounce = null;
        const observer = new MutationObserver(() => {
            syncStatus();
            injectButton();
            clearTimeout(resizeDebounce);
            resizeDebounce = setTimeout(autoFitNameColumn, 100);
        });

        observer.observe(document.body, { childList: true, subtree: true });

        injectButton();
        fetchCloudData();
        setTimeout(autoFitNameColumn, 500);
    }
})();
